VALUES (NULL, NULL, 252839, 'Towerborne', 'Towerborne', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod574.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2ck1.jpg', 'The Belfry stands as a beacon of hope and safety amongst the ruins of humanity and the City of Numbers, with monsters lurking right outside the tower’s walls. You are an Ace, born anew from the spirit realm with the skills, the grit, and the determination to protect the people of the Belfry.', 'https://www.igdb.com/games/towerborne', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 10.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
