VALUES (NULL, NULL, 398, 'Final Fantasy XII', 'Final Fantasy XII', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3rhx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/x3hycfjthaemndqapi4p.jpg', 'The game takes place in the fictional land of Ivalice, where the empires of Archadia and Rozarria are waging an endless war. Dalmasca, a small kingdom, is caught between the warring nations. When Dalmasca is annexed by Archadia, its princess, Ashe, creates a resistance movement. During the struggle, she meets Vaan, a young adventurer who dreams of commanding an airship. They are quickly joined by a band of allies; together, they rally against the tyranny of the Archadian Empire.', 'https://www.igdb.com/games/final-fantasy-xii', '["PlayStation 2"]', NULL, 8.7, 0, 10.71, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
