INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 3002, 'Dragon''s Crown', 'Dragon''s Crown', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wc6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jxzqfvmkhhlorci4y001.jpg', 'Dragon''s Crown is a multiplayer hack-and-slash beat''em up game with breathtaking visual style, a design built around cooperative play, epic boss fights, and the ability to discover a new adventure in every play session. Developer Vanillaware deftly marries stunning hand-drawn and animated art work with deep, action-packed hardcore gameplay. Dragon''s Crown allows up to four players to team up locally or online to clear out monster-ridden dungeons, discover precious treasure, and destroy awe-inspiring bosses. Its unique, highly replayable design means that every time players can boot up and log on, they can expect a different experience. Unparalleled in their unique style, Vanillaware painstakingly hand-paints every detail, be it a blade of grass or the scales on the game''s impressive dragons. The game becomes a lush, vibrant storybook come to life when everything starts to animate in gorgeous full HD.', 'https://www.igdb.com/games/dragon-s-crown', '["PlayStation 3", "Wii", "PlayStation Vita", "Dreamcast"]', NULL, 8.0, 0, 1.0629999999999999e+01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
