VALUES (NULL, NULL, 234, 'Guild Wars', 'Guild Wars', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coay80.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4rx9.jpg', 'In a world torn by conflict, where human kingdoms are all but destroyed and guilds sacrifice all for a chance to control the Hall of Heroes, a champion must rise from the ruins of a once-proud land to lead refugees from the ashes and fulfill an ancient prophecy. Will that hero be you?', 'https://www.igdb.com/games/guild-wars', '["PC (Microsoft Windows)"]', NULL, 8.5, 0, 9.51, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
