VALUES (NULL, NULL, 68353, 'Unicorn Overlord', 'Unicorn Overlord', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7310.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2iyr.jpg', 'From the masterminds that brought 13 Sentinels: Aegis Rim and Odin Sphere, ATLUS x Vanillaware presents the rebirth of tactical fantasy RPG. Fight against fate and embark on a royal adventure to regain your reign alongside trustworthy allies.

Unicorn Overlord combines the timeless tactical RPG genre with overworld exploration and innovative battle system for a unique epic fantasy experience in the iconic Vanillaware style.

Traverse a vibrant world, assemble units and direct them into exquisitely animated battles. Perform heroic deeds and grow renown throughout the five nations. Cultivate a grand army with over 60 unique characters, from humans and elves to massive beasts and heavenly angels', 'https://www.igdb.com/games/unicorn-overlord--1', '["Xbox Series X|S", "PlayStation 4", "PlayStation 5", "Nintendo Switch"]', NULL, 8.5, 0, 10.51, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
