VALUES (NULL, NULL, 1204, 'Tales of Symphonia', 'Tales of Symphonia', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1peo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m5k.jpg', 'In a dying world, legend has it that a Chosen One will one day rise from amongst the people and the land will be reborn. The line between good and evil blurs in this epic adventure where the fate of two interlocked worlds hangs in the balance.', 'https://www.igdb.com/games/tales-of-symphonia', '["Nintendo GameCube"]', NULL, 8.9, 0, 10.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
