VALUES (NULL, NULL, 42808, 'Grand Knights History', 'Grand Knights History', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ywg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scey5o.jpg', 'Grand Knights History is a set in the fantasy world of Rystia, which is divided into three warring kingdoms: Logres, the Ancient Kingdom, ruled by King Fausel; Union, the Kingdom of Knights, ruled by King Leon; and Avalon, the Kingdom of Magic, ruled by Queen Muse. Players must align themselves to one of the three nations and advance the story by taking part in missions on behalf of their chosen country.', 'https://www.igdb.com/games/grand-knights-history', '["PlayStation Portable"]', NULL, NULL, 0, 9.52, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
