VALUES (NULL, NULL, 26602, 'Metaphor: ReFantazio', 'Metaphor: ReFantazio', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8d9t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3moq.jpg', 'From the creative minds of the Persona series – Metaphor: ReFantazio marks ATLUS’ first ever, full-scale fantasy RPG, brought to you by director Katsura Hashino, character designer Shigenori Soejima, and composer Shoji Meguro.

Write your destiny and rise above fear as you step into a fantasy world unlike anything you’ve seen before. Fraught with unsettling mystery, the kingdom stands on a precipice. Now, you must embark on a journey, overcoming obstacles and forging bonds with friends.', 'https://www.igdb.com/games/metaphor-refantazio', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.9, 0, 6.525, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
