VALUES (NULL, NULL, 11667, 'Dragon Quest XI: Echoes of an Elusive Age', 'Dragon Quest XI: Echoes of an Elusive Age', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x9d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5cd1.jpg', 'Dragon Quest XI continues the gameplay of previous games in the series, in which players explore worlds and fight against various monsters, including the ability to explore high areas. Before entering battle, players can also toggle between the 3D and 2D graphical styles. The game features the series'' traditional turn-based battle system.', 'https://www.igdb.com/games/dragon-quest-xi-echoes-of-an-elusive-age', '["PlayStation 4", "PC (Microsoft Windows)"]', NULL, 8.4, 0, 10.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
