VALUES (NULL, NULL, 4004, 'Metal Arms: Glitch in the System', 'Metal Arms: Glitch in the System', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wa8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7ip7.jpg', 'Metal Arms: Glitch in the System is a third-person shooter action-adventure video game, developed by Swingin'' Ape Studios and released in 2003. The game follows a robot named Glitch as he joins forces with the Droids in their fight against General Corrosive and his Milbots.', 'https://www.igdb.com/games/metal-arms-glitch-in-the-system', '["Xbox", "Nintendo GameCube", "Xbox 360", "PlayStation 2"]', NULL, 7.7, 0, 9.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
