VALUES (NULL, NULL, 100413, 'Watch Dogs: Legion', 'Watch Dogs: Legion', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocsvn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar66b.jpg', 'In Watch Dogs: Legion, near future London is facing its downfall... Unless you do something about it. Build a resistance, fight back, and give the city back to the people. It''s time to rise up.', 'https://www.igdb.com/games/watch-dogs-legion', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.4, 0, 5.87, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
