VALUES (NULL, NULL, 173091, 'Wanted: Dead', 'Wanted: Dead', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5jfb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tt3.jpg', 'Wanted: Dead promises "spectacular melee combat and exciting gunplay," and is set in a "dark and dangerous version of science-fiction Hong Kong where you will need sharpened skills to survive."', 'https://www.igdb.com/games/wanted-dead', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 5.7, 0, 9.51, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
