VALUES (NULL, NULL, 165432, 'Spine', 'Spine', 'game', 2027, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocrsi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6ipd.jpg', 'Experience Gun Fu like never before with SPINE, an immersive and highly cinematic action game set in a cyberpunk world. Explore the realistic vision of a near-future with a rebellious street artist Redline and her sentient combat implant, Spine, as they challenge a totalitarian AI regime in search of Redline’s captured brother. Participate in epic gunfights against charismatic opponents, while performing spectacular choreography with firearms!', 'https://www.igdb.com/games/spine', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 9.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
