VALUES (NULL, NULL, 2413, 'Oni', 'Oni', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lcb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57tq.jpg', 'An intense action anime thriller comes to life in Oni. As an elite member of the tech crimes task force, Konoko is an agent on a mission to fight the evil Syndicate. But things are not always as they seem... Konoko is haunted by unknown demons of her past, and the truth threatens to send her over the edge.', 'https://www.igdb.com/games/oni', '["PC (Microsoft Windows)", "Mac", "PlayStation 2"]', NULL, 7.8, 0, 9.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
