VALUES (NULL, NULL, 7032, 'Kane & Lynch: Dead Men', 'Kane & Lynch: Dead Men', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co44f7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arloq.jpg', 'A squad-based shooter centering around the uneasy alliance between ex-military mercenary Adam ''Kane'' Marcus and the psychopathic James Lynch.', 'https://www.igdb.com/games/kane-lynch-dead-men', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 6.2, 0, 9.28, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
