VALUES (NULL, NULL, 4216, 'True Crime: Streets of LA', 'True Crime: Streets of LA', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p3n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/spwn5po3u4l47luwwwop.jpg', 'True Crime: Streets of LA is a free-roaming driving and action game similar in concept to Grand Theft Auto III. The game''s structure is mission-based; most of the missions are dictated by the story and initiate following a cutscene that advances it. Failing a mission still allows the player to continue playing through the chapter and undertake subsequent missions; in some cases this will lead to branching paths and optional missions. However, in order to complete the whole chapter the player must eventually succeed in all the main missions.', 'https://www.igdb.com/games/true-crime-streets-of-la', '["Xbox", "Nintendo GameCube", "PC (Microsoft Windows)", "Mac", "PlayStation 2"]', NULL, 7.2, 0, 9.28, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
