INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 4215, 'True Crime: New York City', 'True Crime: New York City', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8bpm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmimf.jpg', 'Be a good cop or a bad cop in the streetwise action game True Crime: New York City. You can explore the authentically modeled streets of New York City as a police officer tracking down criminals and administering justice. The game features a diverse weapon set, as well as a mixed offering of fighting styles that you can use to take out those who stand in your way. In addition to combat on foot, the game features driving sequences and shootouts. Laurence Fishburne, Christopher Walken, and Mickey Rourke contribute their voice talent to the game as well.', 'https://www.igdb.com/games/true-crime-new-york-city', '["Xbox", "Nintendo GameCube", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 6.5, 0, 8.78, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
