VALUES (NULL, NULL, 576, 'DC Universe Online', 'DC Universe Online', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u18.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcqi.jpg', 'DC Universe Online is a free-to-play superhero / supervillian MMORPG that lets players create their own unique tights-wearing hero or villain and roam the streets of places like Gotham City and Metropolis fighting or creating crime. Players fight alongside such iconic DC Comics characters as Superman and Batman, Lex Luthor and The Joker, and many others. Excellent physics help bring comic book action and combat to life, all under the creative direction of noted comic book artist Jim Lee.', 'https://www.igdb.com/games/dc-universe-online', '["Xbox Series X|S", "PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.9, 0, 9.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
