VALUES (NULL, NULL, 141538, 'The Callisto Protocol', 'The Callisto Protocol', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ymo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1nxg.jpg', 'In this narrative-driven, third-person survival horror game set 300 years in the future, the player will take on the role of Jacob Lee – a victim of fate thrown into Black Iron Prison, a maximum-security penitentiary located on Jupiter''s moon, Callisto. When inmates begin to transform into monstrous creatures, the prison is thrown into chaos.', 'https://www.igdb.com/games/the-callisto-protocol', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.7, 0, 9.56, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
