VALUES (NULL, NULL, 325611, 'Intergalactic: The Heretic Prophet', 'Intergalactic: The Heretic Prophet', 'game', 2027, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co95gc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6olw.jpg', 'Set thousands of years in the future, Intergalactic: The Heretic Prophet puts players into the role of Jordan A. Mun, a dangerous bounty hunter who ends up stranded on Sempiria – a distant planet whose communication with the outside universe went dark hundreds of years ago. Jordan will have to use all her skills and wits if she hopes to be the first person in over 600 years to leave its orbit.', 'https://www.igdb.com/games/intergalactic-the-heretic-prophet', '["PlayStation 5"]', NULL, NULL, 0, 8.53, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
