VALUES (NULL, NULL, 252485, 'John Carpenter''s Toxic Commando', 'John Carpenter''s Toxic Commando', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob0lw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2cgc.jpg', 'Take control of one of the commandos, team up with your friends and send the Sludge God and its horde of things-that-should-never-be back to the underworld. Choose the class that matches your playstyle, pile into your favorite ride, and unload an array of gunfire, grenades, special abilities, and freaking katanas as you save the planet.', 'https://www.igdb.com/games/john-carpenters-toxic-commando', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.7, 0, 9.35, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
