VALUES (NULL, NULL, 320144, 'FBC: Firebreak', 'FBC: Firebreak', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9p0f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nz7.jpg', 'FBC: Firebreak is a 3-player cooperative first-person shooter set within the enigmatic Federal Bureau of Control (FBC). As the Bureau’s headquarters faces a deadly and prolonged siege by otherworldly forces, only Firebreak—its most adaptable response unit—has the skills and courage to restore order.', 'https://www.igdb.com/games/fbc-firebreak', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 6.0, 0, 9.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
