VALUES (NULL, NULL, 79824, 'Old School RuneScape', 'Old School RuneScape', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mo1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6cel.jpg', 'Relive the challenging levelling system and risk-it-all PvP of the biggest retro styled MMO. Play with millions of other players in this piece of online gaming heritage where the community controls the development so the game is truly what you want it to be!', 'https://www.igdb.com/games/old-school-runescape', '["Android", "PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 7.7, 0, 1.1, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
