INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 939, 'Wizardry 8', 'Wizardry 8', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28fv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6xj.jpg', 'The universe is in the throes of violent upheaval and change. Vast and mysterious forces are preparing for the final confrontation. A small group of heroes from distant lands must plunge into the heart of the maelstrom, to uncover long-forgotten secrets, and bring about a new era. Should they succeed, they will gain the powers of the gods themselves. If they fail, countless worlds will fall into the grip of darkness.

Wizardry 8 raises the standard for fantasy role-playing with a vengeance. Prepare yourself for a new level of excitement, immersiveness and depth that made role-playing games one of the best-selling, best-loved genres of all time.

Prepare to experience the culmination of a prestigious RPG series. Enter a vast world of intrigue and wonder. Unravel a gripping, non-linear storyline. Battle your way to victory using your swords, your magic, and your wits. Compete with rivals or align with allies as you struggle to ascend to the Cosmic Circle. Take the battle to the dreaded Dark Savant in Wizardry 8, the phenomenal conclusion to the Dark Savant trilogy, one of the most extensive and challenging stories ever told in classic role-playing games!', 'https://www.igdb.com/games/wizardry-8', '["PC (Microsoft Windows)", "Mac"]', NULL, 8.0, 0, 1.04, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
