VALUES (NULL, NULL, 268309, 'Caribbean Legend', 'Caribbean Legend', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co981v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2jnh.jpg', 'An open-world RPG set in the Golden Age of Caribbean piracy. Embark on a 200-hour-long adventure, plunder cities and ships, explore the unknown, discover treasures, forge friendships, earn bounties on your head, and charm the ladies on your path to ultimate freedom!', 'https://www.igdb.com/games/caribbean-legend', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
