VALUES (NULL, NULL, 489, 'Rift', 'Rift', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod3sh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arel9.jpg', 'Rift (previously known as Rift: Planes of Telara) is a fantasy free-to-play massively multiplayer online role-playing game (MMORPG) developed by Trion Worlds. Rift takes place within the fantasy world of Telara. The game was released in March 2011.

Two competing factions composed of a selection of races and classes battle each other; as well as the enemies who emerge from dynamic rifts.', 'https://www.igdb.com/games/rift', '["Linux", "PC (Microsoft Windows)"]', NULL, 7.6, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
