VALUES (NULL, NULL, 3802, 'Risen 2: Dark Waters', 'Risen 2: Dark Waters', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rje.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5qlu.jpg', 'Set several years after the end of Risen, raging titans have devastated the world and pushed humanity to the brink of existence. Subsequently, monstrous creatures have risen from the watery depths of the sea and their attacks have brought all seafaring to a grinding halt.', 'https://www.igdb.com/games/risen-2-dark-waters', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 6.7, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
