VALUES (NULL, NULL, 245825, 'Erenshor', 'Erenshor', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hb6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar38wk.jpg', 'Erenshor is a single player nod to the MMORPGs of the past. Created specifically for the nostalgic gamer who no longer wants to commit to online or scheduled play times, it offers unrestricted exploration, strategic battles, and countless weapons, armors, and spells to discover.', 'https://www.igdb.com/games/erenshor', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
