VALUES (NULL, NULL, 398217, 'DragonSword: Awakening', 'DragonSword: Awakening', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobx46.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5rex.jpg', 'Explore the anime-style open world of the Continent of Orbis, brought to life with Unreal Engine 5! Recruit unique companions, unleash spectacular Status Ailment tag-team action, and embark on an epic journey to save the world from the threat of a Dragon reawakened after 60 years.', 'https://www.igdb.com/games/dragonsword-awakening', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.04, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
