VALUES (NULL, NULL, 43559, 'Hype: The Time Quest', 'Hype: The Time Quest', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6vj5.jpg', NULL, 'Hype: The Time Quest is an adventure video game developed by Ubi Soft Montreal and published by Ubi Soft Entertainment. The game, released in the year 1999 along with Alex Builds His Farm (1999), is based on the medieval castle toy series from Playmobil. The U.S. version of the Game Boy Color version was supposed to be released in June 2000, but was delayed for over a year for some reason. The game revolves around Hype, a 22-year-old knight in the service of King Taskan IV, following a quest through time to return to his own era in order to save the kingdom from the evil black knight Barnak. The game was directed by Alain Tascan and featured thirty-two different voice actors, as well as original music by Robbi Finkel.', 'https://www.igdb.com/games/hype-the-time-quest', '["Nintendo 64", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 7.1, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
