VALUES (NULL, NULL, 1271, 'Ōkami', 'Ōkami', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3mpk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ptqfhx5g1vecx4rkkpek.jpg', 'Set sometime in classical Japanese history, Ōkami combines several Japanese mythology and folklore to tell the story of how the land was saved from darkness by the Shinto sun goddess named Amaterasu, who took the form of a white wolf with celestial markings covering its fur. It features a distinct sumi-e-inspired cel-shaded visual style and the Celestial Brush, a gesture-system used to perform miracles.', 'https://www.igdb.com/games/okami', '["PlayStation 3", "Wii", "PlayStation 2"]', NULL, 8.9, 0, 1.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
