VALUES (NULL, NULL, 285495, 'Granvir', 'Granvir', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa9x9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar40fw.jpg', 'Granvir is an action roguelite featuring mech building. Scavenge the battlefield for parts to replace and upgrade your arms, legs, torso and weaponry. PIlot your Granvir and manage your campaign between battles to find the best equipment and stay supplied.', 'https://www.igdb.com/games/granvir', '["Linux", "PC (Microsoft Windows)"]', NULL, NULL, 0, 1.04, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
