VALUES (NULL, NULL, 51364, 'Heavy Gear', 'Heavy Gear', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gvk.jpg', NULL, 'In a distant future on a planet called Terra Nova an epic war is waged between the AST and the ECEF. You are a "gear" pilot for one of these sides as you join the battle for supremacy. You pilot the various Heavy Gears (large Biped fighting robots) in a variety of mission either playing through the storyline for both factions or participating in the endless dynamic war going on between the two. As you get promoted you gain access to better gears and more destructive weaponry to accomplish your goals.', 'https://www.igdb.com/games/heavy-gear', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
