VALUES (NULL, NULL, 149398, 'Battlemetal', 'Battlemetal', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3m0h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfkl.jpg', 'Battlemetal is a successor to the 90''s mech simulators of old. A delightful modernization of commanding giant robots bristling with firepower. Players choose and customize their war machines known as METALS, and then drop into the blighted world of Geiserath.', 'https://www.igdb.com/games/battlemetal', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
