VALUES (NULL, NULL, 5491, 'Armored Core 4', 'Armored Core 4', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ki0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sxbdymiqquzr0lcc1nzl.jpg', 'Armored Core, the mech action game that defined the mech genre is back to take on next-generation platforms! Armored Core 4 reinvigorates the brand by offering an all-new storyline, new environments, and online capability. The 10th anniversary of the acclaimed franchise is punctuated with a leap to next-generation platforms that will ensure a new quality level in both gameplay and visual performance.', 'https://www.igdb.com/games/armored-core-4', '["PlayStation 3", "Xbox 360"]', NULL, 7.0, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
