VALUES (NULL, NULL, 2584, 'Eve Online', 'Eve Online', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cociug.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar46g7.jpg', 'EVE Online is a free MMORPG sci-fi strategy game where you can embark on your own unique space adventure. EVE''s open world MMORPG sandbox, renowned among online space games, lets you choose your own path and engage in combat, exploration, industry and much more.', 'https://www.igdb.com/games/eve-online', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.8, 0, 1.07, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
