VALUES (NULL, NULL, 9815, 'Fractured Space', 'Fractured Space', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1nrf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/m29rwtu8b3xvcph1tbxb.jpg', 'Fractured Space is a 5-v-5 team-based space combat game. Control your gigantic capital ship to seize mines and bases for team resources and buffs. The intensity of a shooter combines with deep tactical decision making as you battle over five sectors to finally capture the enemy team''s home', 'https://www.igdb.com/games/fractured-space', '["PC (Microsoft Windows)"]', NULL, 6.9, 0, 1.75, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
