VALUES (NULL, NULL, 213016, 'Esoteric Ebb', 'Esoteric Ebb', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobakp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar53yn.jpg', 'ESOTERIC EBB is a single-player CRPG inspired by the freedom of tabletop adventures. Unravel a political conspiracy with your goblin sidekick. Roll dice in tense encounters. Become a cleric of legends or completely ruin the campaign.', 'https://www.igdb.com/games/esoteric-ebb', '["PC (Microsoft Windows)"]', NULL, 8.2, 0, 1.12, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
