VALUES (NULL, NULL, 2064, 'Antichamber', 'Antichamber', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coado3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yscmyjbrep7i8hztdusr.jpg', 'Antichamber is a single-player first-person puzzle-platform video game. Many of the puzzles are based on phenomena that occur within the Impossible Objects created by the game engine, such as passages that lead the player to different locations depending on which way they face, and structures that seem otherwise impossible within normal three-dimensional space. The game includes elements of psychological exploration through brief messages of advice to help the player figure out solutions to the puzzles as well as adages for real life.', 'https://www.igdb.com/games/antichamber', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.2, 0, 1.09, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
