VALUES (NULL, NULL, 14741, 'Psychonauts 2', 'Psychonauts 2', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob7mx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4lj.jpg', 'Psychonauts 2 is a platform-adventure game developed by Double Fine Productions and released in 2021. It continues the story of Razputin “Raz” Aquato, a young psychic who joins the international psychic espionage agency known as the Psychonauts.
Gameplay combines platforming, exploration, and combat with psychic abilities such as telekinesis, pyrokinesis, and mental connection. Players journey through imaginative levels set inside characters’ minds, each reflecting their personalities and struggles.', 'https://www.igdb.com/games/psychonauts-2', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.7, 0, 1.13, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
