VALUES (NULL, NULL, 9643, 'Return of the Obra Dinn', 'Return of the Obra Dinn', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27j9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbl3.jpg', 'In this 1-bit first-person mystery game, a merchant ship called the Obra Dinn has appeared at a London harbor, years after being declared lost at sea. As an insurance adjuster, the player must examine the ship for clues.', 'https://www.igdb.com/games/return-of-the-obra-dinn', '["PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 9.2, 0, 10.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
