VALUES (NULL, NULL, 54789, 'MudRunner', 'MudRunner', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1m95.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpa8.jpg', 'Like Spintires before it, Spintires: MudRunner puts players in the driver seat and dares them to take charge of incredible all-terrain vehicles, venturing across extreme Siberian landscapes with only a map and compass as guides! This edition comes complete with a brand new Sandbox Map joining the original game''s 5 environments, a total graphical overhaul, a new Challenge mode with 9 new dedicated maps, 13 new vehicles and other comprehensive improvements.', 'https://www.igdb.com/games/mudrunner', '["Xbox Series X|S", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.4, 0, 10.08, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
