VALUES (NULL, NULL, 152287, 'Dahlia View', 'Dahlia View', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zzo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar18df.jpg', 'When 8-year-old Charlotte May is reported missing from Dahlia View, retired detective Robert Conway launches his own investigation into her disappearance. Lead the investigation and uncover dark secrets in a story-driven observational thriller from the creators of The Occupation and Ether One.', 'https://www.igdb.com/games/dahlia-view', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.9, 0, 8.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
