VALUES (NULL, NULL, 394664, 'Cordura', 'Cordura', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobrbi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ji3.jpg', 'Cordura is a 4-player online co-op psychological horror where sanity is your most scarce resource. Venture together into shifting procedural Victorian labyrinths where the environment is never the same. Lose your sanity and the Night will mimic your team to feed your paranoia. Extract and survive.', 'https://www.igdb.com/games/cordura', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 8.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
