VALUES (NULL, NULL, 31699, 'Deadlock', 'Deadlock', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3o8e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ariwu.jpg', 'Deadlock is a virtual reality arcade shooter that pits you against waves of enemies who will stop at nothing to destroy you. Face down tactical troopers, flying drones and vicious attack dogs. It''s kill or be killed, and to get the high score you''ll need light feet, fast reflexes and a steady aim.', 'https://www.igdb.com/games/deadlock', '["SteamVR"]', NULL, 7.0, 0, 8.51, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
