VALUES (NULL, NULL, 314265, 'Reanimal', 'Reanimal', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc21i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4pr1.jpg', 'The creators of Little Nightmares I & II have returned to take you on a darker, more terrifying journey than ever before. In this horror adventure game, a brother & sister go through hell to rescue their missing friends and escape the island that they used to call home.', 'https://www.igdb.com/games/reanimal', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.1, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
