VALUES (NULL, NULL, 134585, 'Sackboy: A Big Adventure', 'Sackboy: A Big Adventure', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4522.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cm9.jpg', 'Iconic PlayStation hero, Sackboy returns in an all-new 3D adventure with a deeply immersive and expressive control scheme. Players can go on this epic platforming journey solo-style, or they can team up with friends for collaborative, chaotic multiplayer fun.', 'https://www.igdb.com/games/sackboy-a-big-adventure', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
