VALUES (NULL, NULL, 89354, 'Supraland', 'Supraland', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yys.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8ga.jpg', 'Supraland is a first-person metroidvania puzzle game. Explore, solve puzzles, beat up monsters, find secret upgrades and new abilities that help you reach new places.', 'https://www.igdb.com/games/supraland', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.3, 0, 1.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
