VALUES (NULL, NULL, 3856, 'Chibi-Robo!', 'Chibi-Robo!', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobx7s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ok4.jpg', 'Like most families, the Sandersons bicker about money and cleaning. Unlike most families, though, they also have robotic spiders, aliens, and talking toys to worry about. Enter Chibi-Robo, a tiny robot programmed to spread happiness. Join him on his quest to restore order to the Sanderson house and SAVE THE WORLD!', 'https://www.igdb.com/games/chibi-robo', '["Nintendo GameCube"]', NULL, 8.0, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
