VALUES (NULL, NULL, 11170, 'Unravel', 'Unravel', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co95jp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7tl.jpg', 'Unravel is a game about Yarny, a tiny character born from a single thread. Yarny embarks on a big adventure into the nature, inspired by the beauty of Northern Scandinavia. Without any spoken words, the character will have to solve puzzles and use tools to overcome tough challenges. All this, in order to find memories of his lost family.
Only Yarny can be the bond that ties everything together in the end.', 'https://www.igdb.com/games/unravel', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 8.0, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
