VALUES (NULL, NULL, 19241, 'Unravel Two', 'Unravel Two', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co95jr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kadeu4i9c7djybcpjnws.jpg', 'Unravel Two is the sequel to the 2015 puzzle platforming game Unravel. In the game there are two Yarny''s (made out of yarn) which can be controlled by one player, though the game can also be played in co-op. Together the Yarny''s explore area''s and solve the puzzles within them.', 'https://www.igdb.com/games/unravel-two', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 7.9, 0, 1.08, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
