VALUES (NULL, NULL, 109458, 'Katamari Damacy Reroll', 'Katamari Damacy Reroll', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25sm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardfc.jpg', 'When the King of All Cosmos accidentally destroys all the stars in the sky, he orders you, his pint-sized princely son, to put the twinkle back in the heavens above. Join the King and Prince of Cosmos on their wacky adventure to restore the stars at home or on the go – now in full HD!', 'https://www.igdb.com/games/katamari-damacy-reroll', '["Google Stadia", "PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.4, 0, 1.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
