VALUES (NULL, NULL, 2702, 'Army Men: Sarge''s War', 'Army Men: Sarge''s War', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45jc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scud82.jpg', 'Army Men: Sarge''s War is a 2004 game in the Army Men video game series. It was initially developed by series creator The 3DO Company but after that company''s bankruptcy was purchased and completed by Global Star Software. The game is more mature and darker than earlier games in the series. Sarge makes no comical moves, holes are blown into soldiers, and the weapons are also made of metal.', 'https://www.igdb.com/games/army-men-sarge-s-war', '["Xbox", "Nintendo GameCube", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 4.8, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
