VALUES (NULL, NULL, 54555, 'UFO 50', 'UFO 50', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24v0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1udh.jpg', 'UFO 50 is a collection of 50 single and multiplayer games from the creators of Spelunky, Downwell, Time Barons, Skorpulac, and Madhouse. Jump in and explore a variety of genres, from platformers and shoot ''em ups to puzzle games and RPGs. Our goal is to combine a familiar 8-bit aesthetic with new ideas and modern game design sensibilities.', 'https://www.igdb.com/games/ufo-50', '["PC (Microsoft Windows)", "Nintendo Switch"]', NULL, 7.4, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
