VALUES (NULL, NULL, 3619, 'Toy Story 2: Buzz Lightyear to the Rescue!', 'Toy Story 2: Buzz Lightyear to the Rescue!', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wv5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1p88.jpg', 'Woody has been stolen from the bedroom, ready to be sold to the highest bidder by an evil toy collector. It''s up to good friend Buzz Lightyear to fight his way through from the bedroom to the outside world in order to save Woody from the toy market and bring him home. All of the character from the 3D animated movie appear through-out the side scroller to help Buzz get to where he is needed. Along with the use of his cannon, Buzz can jump to hard to reach places, also useful in collecting the hidden coins that open bonus levels.', 'https://www.igdb.com/games/toy-story-2-buzz-lightyear-to-the-rescue', '["Nintendo 64", "PC (Microsoft Windows)", "PlayStation", "Dreamcast"]', NULL, 7.1, 0, 1.03, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
