VALUES (NULL, NULL, 383882, 'Burglin'' Gnomes', 'Burglin'' Gnomes', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob6ob.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5141.jpg', 'An online Co-op game about breaking into houses and causing havoc as a tiny gnome. Avoid danger, repurpose stolen household items, and complete tasks to meet the High-Gnome’s demands. Craft equipment and upgrade your home to make your missions easier and more successful.', 'https://www.igdb.com/games/burglin-gnomes', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
