VALUES (NULL, NULL, 5417, 'Twisted Metal: Small Brawl', 'Twisted Metal: Small Brawl', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8qkg.jpg', NULL, 'Twisted Metal: Small Brawl is a vehicular combat game in which the player takes control of one of twelve unique remote control vehicles. While in control of a vehicle, the player can accelerate, steer, brake, reverse, activate the turbo, turn tightly, toggle between and activate weapons using the game controller''s d-pad, analog sticks and buttons.', 'https://www.igdb.com/games/twisted-metal-small-brawl', '["PlayStation"]', NULL, 6.3, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
