VALUES (NULL, NULL, 119278, 'Small Saga', 'Small Saga', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5bph.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhbe.jpg', 'Small Saga is a turn-based RPG that takes place in a medieval rodent society beneath the streets of modern London. The story follows Verm, a particularly angry mouse armed with a pen knife, who is hunting for the human who stole his tail. On the way, Verm befriends a mole wizard, a squirrel harlequin, and a lab rat lancer. Together, the party upend rodent society, clash with titans, and eventually face off against the gods themselves.', 'https://www.igdb.com/games/small-saga', '["PC (Microsoft Windows)", "Mac", "Nintendo Switch"]', NULL, NULL, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
