VALUES (NULL, NULL, 144072, 'Hot Wheels Unleashed', 'Hot Wheels Unleashed', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2u4x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argog.jpg', 'Collect the best vehicles in the Hot Wheels universe, build spectacular tracks and dive into breathtaking races. The most iconic and sought after Hot Wheels vehicles are waiting for you. Get ready to make them race at full speed!', 'https://www.igdb.com/games/hot-wheels-unleashed', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.0, 0, 1.04, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
