VALUES (NULL, NULL, 251471, 'Hot Wheels Unleashed 2: Turbocharged', 'Hot Wheels Unleashed 2: Turbocharged', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6kko.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2bz5.jpg', 'The world’s raddest cars are back and taking the fun to the next level! Race over 130 vehicles with crazy new mechanics and even more vehicle types. Plus, build your tracks with stunning new environments and different game modes to have fun off and online!', 'https://www.igdb.com/games/hot-wheels-unleashed-2-turbocharged', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.0, 0, 1.04, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
