VALUES (NULL, NULL, 137206, 'Manor Lords', 'Manor Lords', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8550.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21h1.jpg', 'Manor Lords is a strategy game that allows you to experience the life of a medieval lord. Grow your starting village into a bustling city, manage resources and production chains, and expand your lands through conquest.

Inspired by the art and architecture of late 14th century Franconia, Manor Lords prioritizes historical accuracy wherever possible, using it to inform gameplay mechanics and visuals alike. Common medieval tropes are avoided in favor of historical accuracy, in order to make the world feel more authentic, colorful, and believable.', 'https://www.igdb.com/games/manor-lords', '["PC (Microsoft Windows)", "Xbox One"]', NULL, 7.8, 0, 1.1, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
