VALUES (NULL, NULL, 13165, 'The Guild 3', 'The Guild 3', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wv3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/oa0cysjarznx2btywrmt.jpg', 'The Guild 3 is a fascinating trade and life simulation that takes place during the late Middle Ages. Step into the shoes of a citiizen, acquire businesses and mansions, produce goods and trade them, start intrigues in politics and society, love, hate, bribe, fight and live through good and bad times!', 'https://www.igdb.com/games/the-guild-3', '["PC (Microsoft Windows)"]', NULL, 6.0, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
