VALUES (NULL, NULL, 2358, 'Chivalry: Medieval Warfare', 'Chivalry: Medieval Warfare', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qqc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arl4k.jpg', 'Chivalry: Medieval Warfare is a fast-paced online multiplayer action game which will have players turning in their guns and grenades for battle axes and swords. Chivalry: Medieval Warfare combines a sharp melee edge and familiar competitive gameplay along with the genuine look and feel of open-field combat in the Middle Ages. Players will use different attacks, blocks and counters insuring that combat is tactical, responsive and of course chaotic.', 'https://www.igdb.com/games/chivalry-medieval-warfare', '["PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Xbox One"]', NULL, 7.1, 0, 1.05, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
