VALUES (NULL, NULL, 274314, 'Kingdom, Dungeon, and Hero', 'Kingdom, Dungeon, and Hero', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ath.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2lqo.jpg', 'You lead one of many kingdoms. Form armies, negotiate, trade or conquer other kingdoms. Hire heroes to explore dungeons, lead armies, govern, or go on missions. Research to increase your power. Construct buildings to improve your kingdom. Easy to learn, difficult to master.', 'https://www.igdb.com/games/kingdom-dungeon-and-hero', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
