VALUES (NULL, NULL, 109668, 'Stay Out of the House', 'Stay Out of the House', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5jad.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tea.jpg', 'Edge of your seat STEALTH HORROR as you try to escape the house of a cannibal SERIAL KILLER....
Stay Out of the House is stealth based, VHS style slasher horror. With low poly visuals authentic to the PS1 era, this is the game your 90''s self always wanted!', 'https://www.igdb.com/games/stay-out-of-the-house', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.9, 0, 1.02, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
