VALUES (NULL, NULL, 346933, 'Aspis', 'Aspis', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9wr6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nly.jpg', 'ASPIS is an atmospheric mystical thriller set in an alternative USSR of the late 80s. You play as a scientist who has lost his family and is involved in a dangerous experiment to create a reality simulation. Explore the cybernetics institute, travel between worlds and encounter a distorted reality', 'https://www.igdb.com/games/aspis', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
