VALUES (NULL, NULL, 13192, 'Paint the Town Red', 'Paint the Town Red', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x7f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arn3j.jpg', 'Paint the Town Red is a chaotic first person melee combat game set in different locations and time periods. The voxel-based enemies can be punched, bashed, kicked, stabbed and sliced completely dynamically using almost anything that isn''t nailed down.', 'https://www.igdb.com/games/paint-the-town-red', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.9, 0, 1.2, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
