VALUES (NULL, NULL, 380437, 'Samson', 'Samson', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coay8a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6lmw.jpg', 'Samson returns to Tyndalston, a city that shaped him hard, where every fight is close and every escape is earned. He owes dangerous people more than he can pay, and they’re using his sister to force his hand. The clock is running. The only way out is through anyone who stands in his way.', 'https://www.igdb.com/games/samson', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 5.6, 0, 1.2, '2026-11-26 23:52:17', '2026-11-26 23:52:17')
