VALUES (NULL, NULL, 138244, 'Midnight Fight Express', 'Midnight Fight Express', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3og0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar112d.jpg', 'Fight your way across the city in a brutal romp that mixes old school brawlers and fast-paced motion-captured combat. You’re Babyface, a former member of the criminal underworld lured back into “the life” by a mysterious AI drone. Your mission against impossible odds: Fight your way across the city before sunrise, and prevent a citywide criminal takeover together.', 'https://www.igdb.com/games/midnight-fight-express', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 7.6, 0, 4.85999999999999943e+00, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
