VALUES (NULL, NULL, 1827, 'Remember Me', 'Remember Me', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2h9u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/o8bhzg51z0tjlmupkp7e.jpg', 'A visionary 3rd person action adventure, Remember Me puts players into the role of Nilin, a former elite memory hunter with the ability to break into people''s minds and steal or even alter their memories. The authorities, fearful of her knowledge and capabilities have arrested Nilin and wiped her memory clean. After her escape from prison, Nilin sets out on a mission to recover her identity, helped by her last and only friend. This search for her past leads to her being hunted by the very people that created this surveillance society.', 'https://www.igdb.com/games/remember-me', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.2, 0, 9.02, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
