VALUES (NULL, NULL, 258775, 'Queen''s Domain', 'Queen''s Domain', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coda8t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4sr2.jpg', 'A retro-fantasy action RPG with brutal combat and traversal-focused exploration. Embark on a quest to find your father who disappeared on the mysterious Isle of Neasied, where sinister forces gather, secrets hide everywhere, and the sleeping Queen has begun to stir…', 'https://www.igdb.com/games/queens-domain', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.5, 0, 1.48033333333333327e+01, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
