VALUES (NULL, NULL, 124333, 'Ultrakill', 'Ultrakill', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co46s3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arlq1.jpg', 'Ultrakill is a fast-paced ultraviolent retro FPS combining the skill-based scoring from character action games with unadulterated carnage inspired by the best shooters of the 90''s. Rip apart your foes with varied destructive weapons and shower in their blood to regain your health.', 'https://www.igdb.com/games/ultrakill', '["PC (Microsoft Windows)"]', NULL, 8.1, 0, 7.68333333333333268e+00, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
