VALUES (NULL, NULL, 1059, 'Kingdoms of Amalur: Reckoning', 'Kingdoms of Amalur: Reckoning', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25rk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ewvmrnziqptrafjktqqm.jpg', 'Kingdoms of Amalur: Reckoning is an epic, open-world role-playing game set in Amalur, a mysterious and magical new fantasy world created by New York Times best-selling author R. A. Salvatore. Brought to life visually through the trademark visceral style of renowned artist and Spawn creator Todd McFarlane, Reckoning brings a new level of intense action combat to the RPG genre.', 'https://www.igdb.com/games/kingdoms-of-amalur-reckoning', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.8, 0, 10.08, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
