VALUES (NULL, NULL, 23733, 'Tunic', 'Tunic', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/td1t8kb33gyo8mvhl2pc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arklp.jpg', 'Tunic is an action adventure about a tiny fox in a big world. Explore the wilderness, discover spooky ruins, and fight terrible creatures from long ago.', 'https://www.igdb.com/games/tunic', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.7, 0, 5.605, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
