VALUES (NULL, NULL, 200903, 'Another Crab''s Treasure', 'Another Crab''s Treasure', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mrs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2x39.jpg', 'Another Crab’s Treasure is a soulslike adventure set in a crumbling underwater world plagued by a mysterious curse. As Kril the hermit crab, you’ll need to wear the trash around you as shells to withstand attacks from enemies many times your size. Embark on an epic treasure hunt to buy back your repossessed shell, and discover the dark secrets behind the polluted ocean.', 'https://www.igdb.com/games/another-crabs-treasure', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.9, 0, 5.51, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
