VALUES (NULL, NULL, 134588, 'Kena: Bridge of Spirits', 'Kena: Bridge of Spirits', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hwy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8zp.jpg', 'Kena: Bridge of Spirits: a story-driven, action adventure combining exploration with fast-paced combat. Untangle the past as Kena, a young Spirit Guide in search of the sacred Mountain Shrine. Help free the spirits trapped in a forgotten village with the help of the Rot, Kena''s adorable (yet powerful) spirit companions.', 'https://www.igdb.com/games/kena-bridge-of-spirits', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.1, 0, 6.08, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
