VALUES (NULL, NULL, 20, 'BioShock', 'BioShock', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mli.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4wvc.jpg', 'BioShock is a horror-themed first-person shooter set in a steampunk underwater dystopia. The player is urged to turn everything into a weapon: biologically modifying their own body with Plasmids, hacking devices and systems, upgrading their weapons, crafting new ammo variants, and experimenting with different battle techniques are all possible. The game is described by the developers as a spiritual successor to their previous PC title System Shock 2. BioShock received high praise in critical reviews for its atmospheric audio and visual quality, absorbing and original plot and its unique gaming experience.', 'https://www.igdb.com/games/bioshock', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 9.0, 0, 1.72223076923076945e+01, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
