VALUES (NULL, NULL, 27091, 'Foxhole', 'Foxhole', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coab4i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhpf.jpg', 'Foxhole is a massively multiplayer game where you will work with hundreds of players to shape the outcome of a persistent online war. Every individual soldier is a player that contributes to the war effort through logistics, base building, reconnaissance, combat, and more.', 'https://www.igdb.com/games/foxhole', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 8.88666666666666671e+00, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
