VALUES (NULL, NULL, 226030, 'Nuclear Option', 'Nuclear Option', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc9ri.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar63yp.jpg', 'Fly near-future aircraft with immersive physics on intense battlefields, facing land, air and sea threats. Wage war against AI or other players with an array of potent weapons. Wield tactical and strategic nuclear weapons, capable of annihilating anything in their path.', 'https://www.igdb.com/games/nuclear-option', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 6.09333333333333282e+00, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
