VALUES (NULL, NULL, 538, 'BioShock Infinite', 'BioShock Infinite', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n12.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4koi.jpg', 'BioShock Infinite is the third game in the BioShock series. It is not a direct sequel/prequel to any of the previous BioShock games but takes place in an entirely different setting, although it shares similar features, gameplay and concepts with the previous games. BioShock Infinite features a range of environments that force the player to adapt, with different weapons and strategies for each situation. Interior spaces feature close combat with enemies, but unlike previous games set in Rapture, the setting of Infinite contains open spaces with emphasis on sniping and ranged combat against as many as fifteen enemies at once.', 'https://www.igdb.com/games/bioshock-infinite', '["PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Xbox One"]', NULL, 8.9, 0, 8.95, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
