VALUES (NULL, NULL, 287629, 'Toy Story 3', 'Toy Story 3', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7sax.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2rii.jpg', 'In the Toy Story 3 help Buzz, Woody and the rest of the Toys ensure no toy gets left behind. Dive into to all new heroic adventures in Story Mode or let your imagination run wild in the exiting new open world of Toy Box Mode! Come and play to infinity and beyond.

PS2/PSP exclusive version of the video game.', 'https://www.igdb.com/games/toy-story-3--2', '["PlayStation Portable", "PlayStation 2"]', NULL, 7.9, 0, 2.02, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
