VALUES (NULL, NULL, 113598, 'Deathloop', 'Deathloop', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4nzt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4u5u.jpg', 'Deathloop transports players to the lawless island of Blackreef in an eternal struggle between two extraordinary assassins. Explore stunning environments and meticulously designed levels in an immersive gameplay experience that lets you approach every situation any way you like. Hunt down targets all over the island in an effort to put an end to the cycle once and for all, and remember, if at first you don’t succeed… die, die again.', 'https://www.igdb.com/games/deathloop', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.5, 0, 9.043333333333333e+00, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
