VALUES (NULL, NULL, 387817, 'The Lantern of the Laughless Saint', 'The Lantern of the Laughless Saint', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobe8o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6csj.jpg', 'A solo or co-op RPG inspired by Morrowind. Drawn by a shared dream, you awaken on an isolated island crowned by a silent Tower. Unravel the mystery of the Laughless Saint, confront the weight of human desire, and decide what deserves to be saved when the light beneath the world finally stirs.', 'https://www.igdb.com/games/the-lantern-of-the-laughless-saint', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 2.075, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
