VALUES (NULL, NULL, 427, 'Final Fantasy VII', 'Final Fantasy VII', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kx2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ypvk6vrobhtnm68obkte.jpg', 'The Western release of Final Fantasy VII (released as Final Fantasy VII International in Japan) included additional elements and alterations, such as streamlining of the menu and Materia system, reducing the health of enemies, new visual cues to help with navigation across the world map, and additional cutscenes relating to Cloud''s past.', 'https://www.igdb.com/games/final-fantasy-vii', '["PlayStation 3", "PlayStation", "PlayStation Portable"]', NULL, 8.8, 0, 6.01, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
