VALUES (NULL, NULL, 25076, 'Red Dead Redemption 2', 'Red Dead Redemption 2', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1q1f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/l0kjrldascktx2kzqhbi.jpg', 'Red Dead Redemption 2 is the epic tale of outlaw Arthur Morgan and the infamous Van der Linde gang, on the run across America at the dawn of the modern age.', 'https://www.igdb.com/games/red-dead-redemption-2', '["Google Stadia", "PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 9.4, 0, 1.8043571428571429e+01, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
