VALUES (NULL, NULL, 90099, 'Tom Clancy''s The Division 2', 'Tom Clancy''s The Division 2', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xrm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hhugqt4h0g07jxpywark.jpg', 'The Division 2 is an action-shooter RPG set in an open-world. Play in co-op and PvP modes that offer more variety in missions and challenges, new progression systems with unique twists and surprises, and fresh gaming innovations to engage players for years to come.', 'https://www.igdb.com/games/tom-clancys-the-division-2', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.0, 0, 5.018, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
