VALUES (NULL, NULL, 11156, 'Horizon Zero Dawn', 'Horizon Zero Dawn', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2una.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4rzl.jpg', 'Welcome to a vibrant world rich with the beauty of nature – but inhabited by awe-inspiring, highly advanced machines. As a young machine hunter named Aloy, you must unravel the mysteries of this world and find your own destiny.', 'https://www.igdb.com/games/horizon-zero-dawn', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.8, 0, 6.285, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
