VALUES (NULL, NULL, 8347, 'The Long Dark', 'The Long Dark', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vga.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar67ev.jpg', 'Welcome to The Long Dark, the innovative exploration-survival experience Wired magazine calls "the pinnacle of an entire genre". The game is a thoughtful, exploration-survival experience that challenges solo players to think for themselves as they explore an expansive frozen wilderness in the aftermath of a geomagnetic disaster. There are no zombies but only you, the cold, and all the threats Mother Nature can muster.', 'https://www.igdb.com/games/the-long-dark', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.9, 0, 1.21171428571428556e+01, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
