VALUES (NULL, NULL, 125624, 'Grounded', 'Grounded', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5d1l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar84r.jpg', 'The world is a vast, beautiful and dangerous place – especially when you have been shrunk to the size of an ant. Explore, build and survive together in this first person, multiplayer, survival-adventure. Can you thrive alongside the hordes of giant insects, fighting to survive the perils of the backyard?', 'https://www.igdb.com/games/grounded', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.6, 0, 6.16666666666666607e+00, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
