VALUES (NULL, NULL, 3042, 'Dying Light', 'Dying Light', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co65yq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6emo.jpg', 'Dying Light is a first-person, action survival horror game set in a vast and dangerous open world. During the day, players traverse an expansive urban environment overrun by a vicious outbreak, scavenging the world for supplies and crafting weapons to defend against the growing infected population. At night, the hunter becomes the hunted, as the infected become aggressive and more dangerous. Most frightening are the predators which only appear after sundown. Players must use everything in their power to survive until the morning’s first light.', 'https://www.igdb.com/games/dying-light', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 7.6, 0, 8.33285714285714362e+00, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
