VALUES (NULL, NULL, 77730, 'Smalland: Survive the Wilds', 'Smalland: Survive the Wilds', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ait.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar12wt.jpg', 'Experience a big adventure on a tiny scale! Enjoy multiplayer survival in a vast, hazardous world. Preparation is key when you''re this small & at the bottom of the food chain. Craft weapons & armour, tame & ride creatures, build encampments & explore a strange new land.', 'https://www.igdb.com/games/smalland-survive-the-wilds', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.4, 0, 2.015, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
