VALUES (NULL, NULL, 847, 'Resident Evil 5', 'Resident Evil 5', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobtgs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yi6lgkwy9z6y5vrnozyi.jpg', 'Resident Evil 5 is the seventh video game in the Resident Evil series. It features similar gameplay to Resident Evil 4 utilizing the same over the shoulder view, but this time the environment plays a significant role. The player is now dependent on his partner more than in older games. When the partner''s health bar drop down to 0, he will enter the dying stage where the health bar will flash red and gradually lower as he stays like this. Resident Evil 5 also features new types of enemies called Majini and mostly are of African descent.', 'https://www.igdb.com/games/resident-evil-5', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.6, 0, 5.88, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
