VALUES (NULL, NULL, 3092, 'The Lord of the Rings Online', 'The Lord of the Rings Online', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5rub.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arouu.jpg', 'Lord of the Rings Online is the premier MMORPG set in J.R.R. Tolkien''s wondrous world of Middle-earth. LOTRO brings you into the timeline of the events of The Lord of the Rings story, and sets you on a path that parallels the Fellowship of the Ring, aiding them on their journey to Mordor by performing tasks and adventurous deeds surrounding their path across Middle-earth.', 'https://www.igdb.com/games/the-lord-of-the-rings-online', '["PC (Microsoft Windows)", "Mac"]', NULL, 8.3, 0, 2.05, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
