VALUES (NULL, NULL, 141114, '007 First Light', '007 First Light', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaoiz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3n69.jpg', '007 First Light is a thrilling espionage action-adventure game from IO Interactive. Players follow James Bond as a young, resourceful, and sometimes reckless recruit in MI6''s training program and discover an origin story of the world''s most famous spy.', 'https://www.igdb.com/games/007-first-light', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 2.16, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
