VALUES (NULL, NULL, 298526, 'Kingdom Come: Deliverance II', 'Kingdom Come: Deliverance II', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8qmv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3s9l.jpg', 'A thrilling story-driven action RPG, with a rich open world, set in 15th century Medieval Europe. Experience the ultimate medieval adventure - through the eyes of young Henry - as you embark on a journey of epic proportions.', 'https://www.igdb.com/games/kingdom-come-deliverance-ii', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.3, 0, 7.26, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
