VALUES (NULL, NULL, 152249, 'Marvel''s Guardians of the Galaxy', 'Marvel''s Guardians of the Galaxy', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co39pu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aruor.jpg', 'Fire up a wild ride across the cosmos with a fresh take on Marvel’s Guardians of the Galaxy. In this action-adventure game, you are Star-Lord leading the unpredictable Guardians from one explosion of chaos to the next. You got this. Probably.', 'https://www.igdb.com/games/marvels-guardians-of-the-galaxy', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.1, 0, 9.02, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
