VALUES (NULL, NULL, 144022, 'Sifu', 'Sifu', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4h5s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar12vu.jpg', 'Sifu is a realistic third-person brawler with tight Kung Fu combat mechanics and cinematic martial arts action embarking you on a path for revenge.', 'https://www.igdb.com/games/sifu', '["Xbox Series X|S", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 5.062, '2026-11-19 20:56:22', '2026-11-26 23:52:17')
