VALUES (NULL, NULL, 305152, 'Clair Obscur: Expedition 33', 'Clair Obscur: Expedition 33', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gam.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nmf.jpg', 'Lead the members of Expedition 33 on their quest to destroy the Paintress so that she can never paint death again. Explore a world of wonders inspired by Belle Époque France and battle unique enemies in this turn-based RPG with real-time mechanics.', 'https://www.igdb.com/games/clair-obscur-expedition-33', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.9, 0, 1.30042857142857144e+01, '2026-11-20 22:18:41', '2026-11-26 23:52:17')
