VALUES (NULL, NULL, 296, 'Crysis', 'Crysis', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2on1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7ws.jpg', 'From the makers of Far Cry, Crysis offers FPS fans the best-looking, most highly-evolving gameplay, requiring the player to use adaptive tactics and total customization of weapons and armor to survive in dynamic, hostile environments including Zero-G.', 'https://www.igdb.com/games/crysis', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.3, 0, 6.02, '2026-11-21 13:07:40', '2026-11-26 23:52:17')
