VALUES (NULL, NULL, 37, 'Dead Space', 'Dead Space', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2g7w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/j9llqq3hq6i8uy8mwefe.jpg', 'Dead Space is a 2008 science fiction survival horror video game developed by EA Redwood Shores (now Visceral Games) for Microsoft Windows, PlayStation 3 and Xbox 360. The game was released on all platforms through October 2008. The game puts the player in control of an engineer named Isaac Clarke, who battles the Necromorphs, reanimated human corpses, aboard an interstellar mining ship, the USG Ishimura.', 'https://www.igdb.com/games/dead-space', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.7, 0, 1.0004999999999999e+01, '2026-11-21 13:07:40', '2026-11-26 23:52:17')
