VALUES (NULL, NULL, 1267, 'Sleeping Dogs', 'Sleeping Dogs', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e3z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/q65bsw4ruvojxqeibdze.jpg', 'Sleeping Dogs is a third-person open-world action-adventure game set in contemporary Hong Kong. Players control Wei Shen, an undercover police officer who infiltrates a Triad organization called the Sun On Yee. Gameplay emphasizes melee combat using martial arts moves, grapples, and environmental attacks over gunplay, alongside driving, parkour, and open-world exploration. The game features a triple experience system split between Triad, Police, and Face progression paths, each unlocking different abilities and rewards.', 'https://www.igdb.com/games/sleeping-dogs', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.2, 0, 9.365, '2026-11-21 21:29:28', '2026-11-26 23:52:17')
