VALUES (NULL, NULL, 132181, 'Resident Evil 4', 'Resident Evil 4', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6bo0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1xhu.jpg', 'Resident Evil 4 is a remake of the 2005 original Resident Evil 4 reimagined for 2023 to bring state-of-the-art survival horror. Resident Evil 4 preserves the essence of the original game, while introducing modernized gameplay, a reimagined storyline,
and vividly detailed graphics to make this the latest survival horror game where life and death, terror and catharsis intersect.', 'https://www.igdb.com/games/resident-evil-4--1', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac"]', NULL, 9.2, 0, 5.58, '2026-11-21 21:29:28', '2026-11-26 23:52:17')
