VALUES (NULL, NULL, 107215, 'SnowRunner', 'SnowRunner', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaazp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5s94.jpg', 'SnowRunner is an off-road driving simulation game that focuses on navigating challenging terrain using a variety of heavy vehicles. Players complete contracts and objectives across open environments, transporting cargo while overcoming mud, snow, rivers, and other natural obstacles.
The game emphasizes realistic physics, vehicle customization, and route planning, with progression tied to upgrading equipment and expanding a fleet suited for different conditions.', 'https://www.igdb.com/games/snowrunner', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.8, 0, 1.54, '2026-11-21 21:29:28', '2026-11-26 23:52:17')
