VALUES (NULL, NULL, 314239, 'RoadCraft', 'RoadCraft', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tyt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nry.jpg', 'As the leader of a company specialized in restoring sites devastated by natural disasters, use your construction machinery to restart the local industry. Clear debris and faulty equipment, rebuild roads and bridges damaged by weather, and much more!', 'https://www.igdb.com/games/roadcraft', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.1, 0, 6.255, '2026-11-21 21:29:28', '2026-11-26 23:52:17')
