VALUES (NULL, NULL, 3049, 'State of Decay', 'State of Decay', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jpa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hqemwmuwnisrdptudyjd.jpg', 'The end is here. Life as you know it has gone to hell after the mother of all zombie outbreaks. Now you and the few scattered survivors must band together to survive and rebuild in a 3rd-person action game set in a dynamic open world. You choose where to make your stand, designing and fortifying your home base, performing daring raids for food and ammunition, and rescuing other playable survivors with unique talents. The open, sandbox world develops in real-time, shaped by your actions, dynamically generating content based on your choices and the ever-increasing zombie threat.', 'https://www.igdb.com/games/state-of-decay', '["PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.5, 0, 6.33, '2026-11-21 21:29:28', '2026-11-26 23:52:17')
