VALUES (NULL, NULL, 19541, 'State of Decay 2', 'State of Decay 2', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2569.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6iq.jpg', 'The next installment in the critically acclaimed “State of Decay” franchise immerses you in an all-new, multiplayer zombie survival fantasy. Build a lasting community, working with other players or solo to overcome challenges while exploring your own unique story in a world that remembers the choices you make.', 'https://www.igdb.com/games/state-of-decay-2', '["PC (Microsoft Windows)", "Xbox One"]', NULL, 7.0, 0, 6.32, '2026-11-21 21:29:28', '2026-11-26 23:52:17')
