VALUES (NULL, NULL, 55189, 'Warhammer: Vermintide 2', 'Warhammer: Vermintide 2', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20u8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar74e.jpg', 'Warhammer: Vermintide 2 is the sequel to the critically acclaimed Vermintide. It''s time for players to return to the memorable first-person co-op experience with intense world class melee action.', 'https://www.igdb.com/games/warhammer-vermintide-2', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.8, 0, 6.3149999999999995e+00, '2026-11-22 03:06:26', '2026-11-26 23:52:17')
