VALUES (NULL, NULL, 25648, 'AI War 2', 'AI War 2', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1h3s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ariy4.jpg', 'AI War II is a grand strategy/RTS hybrid against an overwhelming, inhuman enemy who has conquered the galaxy. The enemy has made only a single error: underestimating you. You must steal as much technology as you can, and take enough territory to fortify your bases and launch your attacks.', 'https://www.igdb.com/games/ai-war-2', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.0, 0, 10.77, '2026-11-23 03:29:46', '2026-11-26 23:52:17')
