VALUES (NULL, NULL, 124042, 'Terra Invicta', 'Terra Invicta', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9fgo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3bol.jpg', 'From the creators of Long War, an alien invasion has fractured humanity into seven ideological factions each with a unique vision for the future. Lead your chosen faction to take control of Earth''s nations, expand across the Solar System, and battle enemy fleets in tactical combat.', 'https://www.igdb.com/games/terra-invicta', '["PC (Microsoft Windows)"]', NULL, 7.1, 0, 11.53, '2026-11-23 15:29:50', '2026-11-26 23:52:17')
