VALUES (NULL, NULL, 250722, 'Eclipsium', 'Eclipsium', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coag01.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2bnu.jpg', 'Eclipsium is a trippy and surreal horror game that will take you on a journey through darkness and confusion. In this haunting and immersive experience, you''ll need to traverse a dark and twisted world to reach a tower that''s looming in the distance.', 'https://www.igdb.com/games/eclipsium', '["PC (Microsoft Windows)"]', NULL, 6.0, 0, 5.755, '2026-11-23 15:29:50', '2026-11-26 23:52:17')
