VALUES (NULL, NULL, 9174, 'Little Nightmares', 'Little Nightmares', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rdi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar759.jpg', 'Little Nightmares is a puzzle-platform horror adventure game developed by Tarsier Studios and published by Bandai Namco Entertainment. Set in a mysterious world, Little Nightmares follows the journey of Six, a hungry little girl who must escape the Maw, an iron vessel inhabited by monstrous, twisted beings.', 'https://www.igdb.com/games/little-nightmares', '["Google Stadia", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "Xbox One", "Nintendo Switch"]', NULL, 7.9, 0, 2.245, '2026-11-24 04:24:23', '2026-11-26 23:52:17')
