VALUES (NULL, NULL, 434, 'Red Dead Redemption', 'Red Dead Redemption', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lcv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3qmq.jpg', 'A modern-day Western epic, Red Dead Redemption takes John Marston, a relic from the fast-closing time of the gunslinger, through an open world filled with wildlife, mini-games, and shootouts. Marston sets out to hunt down his old gang mates for the government, who have taken away his family. Along his journey, he meets many characters emblematic of the Wild West, heroism, and the new civilization.', 'https://www.igdb.com/games/red-dead-redemption', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 9.0, 0, 10.6375, '2026-11-24 04:24:23', '2026-11-26 23:52:17')
