VALUES (NULL, NULL, 116200, 'Back 4 Blood', 'Back 4 Blood', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mhj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ary49.jpg', 'Back 4 Blood is a thrilling cooperative first-person shooter from the creators of the critically acclaimed Left 4 Dead franchise. You are at the center of a war against the Ridden. These once-human hosts of a deadly parasite have turned into terrifying creatures bent on devouring what remains of civilization. With humanity’s extinction on the line, it’s up to you and your friends to take the fight to the enemy, eradicate the Ridden, and reclaim the world.', 'https://www.igdb.com/games/back-4-blood', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.3, 0, 10.26, '2026-11-24 04:24:23', '2026-11-26 23:52:17')
