VALUES (NULL, NULL, 249998, 'Kiborg', 'Kiborg', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tma.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2bg5.jpg', 'Kiborg is a fast-paced, story-driven action game with rogue-lite encounters. Each challenge is unique and the narrative always moves forward, win or lose. Become an unstoppable war machine and face the consequences of your actions as you lead a resistance group on a faraway prison planet.', 'https://www.igdb.com/games/kiborg', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 5.76500000000000056e+00, '2026-11-26 02:21:07', '2026-11-26 23:52:17')
